insert into public.categories (id, name_sq, name_en, intro_sq, intro_en, sort) values
  ('bridal', 'Nusëri', 'Bridal', 'Fustane nusërie të punuara me dorë në Prizren, në masat standarde ose të qepura sipas masave të tua.', 'Handmade wedding dresses from Prizren, in standard sizes or cut to your measurements.', 1),
  ('evening', 'Mbrëmje', 'Evening', 'Fustane mbrëmjeje për ceremoni, darka dhe netë që mbahen mend.', 'Evening dresses for ceremonies, dinners and nights worth remembering.', 2),
  ('short', 'Të shkurtra', 'Short', 'Fustane të shkurtra për kurorëzimin civil, festat dhe mbrëmjet më të lira.', 'Short dresses for civil ceremonies, celebrations and lighter evenings.', 3)
insert into public.measurement_definitions (id, kind, view, label_sq, label_en, hint_sq, hint_en, min_cm, max_cm, always_required, sort) values
  ('height', 'straight', 'front', 'Gjatësia e trupit', 'Height', 'Zbathur, drejt pranë murit, nga dyshemeja deri në majë të kokës.', 'Barefoot, standing straight against a wall, from the floor to the top of your head.', 140, 200, true, 1),
  ('bust', 'around', 'front', 'Perimetri i gjoksit', 'Bust circumference', 'Rreth pjesës më të plotë të gjoksit, me shiritin drejt përmes shpinës.', 'Around the fullest part of your bust, with the tape level across your back.', 70, 150, true, 2),
  ('underbust', 'around', 'front', 'Perimetri nën gjoks', 'Under bust circumference', 'Menjëherë nën gjoks, aty ku qëndron shiriti i sutjenës.', 'Directly under your bust, where a bra band sits.', 60, 130, true, 3),
  ('waist', 'around', 'front', 'Perimetri i belit', 'Waist circumference', 'Rreth pjesës më të ngushtë të belit, zakonisht pak mbi kërthizë.', 'Around the narrowest part of your waist, usually just above the navel.', 50, 140, true, 4),
  ('hips', 'around', 'side', 'Perimetri i vitheve në pjesën më të gjerë', 'Hip circumference at the fullest part', 'Me këmbët bashkë, rreth pjesës më të plotë të vitheve.', 'Feet together, around the fullest part of your seat.', 75, 160, true, 5),
  ('shoulder_width', 'straight', 'back', 'Gjerësia e shpatullave', 'Shoulder width', 'Përmes shpinës, nga maja e njërës shpatull te maja e tjetrës.', 'Across your back, from one shoulder point to the other.', 30, 55, true, 6),
  ('hollow_to_floor', 'straight', 'front', 'Nga gropëza e qafës deri në dysheme', 'Hollow to floor', 'Zbathur, nga gropëza në fund të qafës drejt poshtë deri në dysheme.', 'Barefoot, from the hollow at the base of your neck straight down to the floor.', 120, 175, true, 7),
  ('heel_height', 'heel', 'shoe', 'Lartësia e takës që do të mbash', 'Heel height you will wear', 'Nga dyshemeja deri aty ku mbështetet thembra. Shkruaj 0 për këpucë pa takë.', 'From the floor to where your heel rests. Enter 0 for flat shoes.', 0, 15, true, 8),
  ('neck', 'around', 'front', 'Perimetri i qafës', 'Neck circumference', 'Rreth bazës së qafës, me një gisht nën shirit.', 'Around the base of your neck, with one finger under the tape.', 28, 50, false, 9),
  ('bicep', 'around', 'front', 'Perimetri i krahut', 'Bicep circumference', 'Rreth pjesës më të plotë të krahut të sipërm, me krahun të lirshëm.', 'Around the fullest part of your upper arm, arm relaxed.', 20, 50, false, 10),
  ('sleeve_length', 'straight', 'side', 'Gjatësia e mëngës', 'Sleeve length', 'Nga maja e shpatullës deri te kocka e kyçit, me krahun pak të përkulur.', 'From the shoulder point to the wrist bone, arm slightly bent.', 40, 70, false, 11),
  ('wrist', 'around', 'front', 'Perimetri i kyçit të dorës', 'Wrist circumference', 'Rreth kyçit të dorës, pak mbi kockën e kyçit.', 'Around your wrist, just above the wrist bone.', 12, 25, false, 12),
  ('front_waist_length', 'straight', 'front', 'Gjatësia e përparme deri në bel', 'Front waist length', 'Nga shpatulla, aty ku takon qafën, mbi majën e gjoksit deri në bel.', 'From where your shoulder meets your neck, over the bust point, down to the waist.', 30, 55, false, 13),
  ('back_length', 'straight', 'back', 'Gjatësia e shpinës', 'Back length', 'Nga kocka në fund të qafës drejt poshtë deri në bel.', 'From the bone at the base of your neck straight down to your waist.', 32, 50, false, 14),
  ('bust_point_height', 'straight', 'front', 'Lartësia e majës së gjoksit', 'Bust point height', 'Nga shpatulla, aty ku takon qafën, deri te maja e gjoksit.', 'From where your shoulder meets your neck down to the bust point.', 18, 35, false, 15),
  ('hollow_to_hem', 'straight', 'front', 'Nga gropëza e qafës deri te fundi', 'Hollow to hem', 'Nga gropëza në fund të qafës deri aty ku dëshiron të përfundojë fustani.', 'From the hollow at the base of your neck to where you want the hem to fall.', 60, 120, false, 16),
  ('waist_to_knee', 'straight', 'side', 'Nga beli deri te gjuri', 'Waist to knee', 'Nga beli natyral deri në mes të gjurit.', 'From your natural waist to the middle of your knee.', 45, 70, false, 17)
